import{_ as r,C as s,c as n,o as l,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Restaurant tables","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/restaurant-tables.md","filePath":"master/sales/point-of-sale/selling/restaurant-tables.md","lastUpdated":1792041590000}'),i={name:"master/sales/point-of-sale/selling/restaurant-tables.md"};function g(h,t,d,p,u,c){const a=s("ImagePopup");return l(),n("div",null,[t[0]||(t[0]=e('<h1 id="restaurant-tables" tabindex="-1">Restaurant tables <a class="header-anchor" href="#restaurant-tables" aria-label="Permalink to &quot;Restaurant tables&quot;">​</a></h1><p>A restaurant register shows a floor plan instead of a plain product grid. You click a table, take the order for that table, and send it on. This page uses the Spice Route Kitchen &amp; Bar register to show the floor plan, a table order, guests, transfers and split orders.</p><blockquote><p><strong>In simple words:</strong> Click the table, add the dishes, and pay when the guests are ready.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Table features turn on in the register. Go to <code>Point of Sale → Configurations → Point of Sale</code>, open the register and use the <strong>Restaurant Mode</strong> tab.</p><ul><li><strong><em>Is a Bar/Restaurant:</em></strong> Turns on tables and preparation tickets. It is locked while a session is open.</li><li><strong><em>Allow Bill Splitting:</em></strong> Adds the <strong>Split</strong> action to a table order.</li><li><strong><em>Early Receipt Printing:</em></strong> Adds the <strong>Bill</strong> action to print a receipt before payment.</li><li><strong><em>Eat in / Take out:</em></strong> Lets you switch an order between dine in and take out.</li><li><strong><em>Floors &amp; Tables Map:</em></strong> Lists the floors and tables of the register.</li></ul><p>See <a href="./../get-started/set-up-a-register.html">Set up a register</a> for the full form.</p><h2 id="the-floor-plan" tabindex="-1">The floor plan <a class="header-anchor" href="#the-floor-plan" aria-label="Permalink to &quot;The floor plan&quot;">​</a></h2><p>Open the terminal and click your register. The <strong>Home</strong> page shows the floor plan.</p>',9)),o(a,{src:"/images1/pos/floor_plan.png",alt:"Spice Route floor plan with the Ground Floor tab, tables T1 to T8 with seats, zoom control, Grid view, Edit plan and New order buttons"}),t[1]||(t[1]=e('<ul><li><strong>Floor tabs:</strong> One tab per floor, such as <strong>Ground Floor</strong> and <strong>Rooftop Lounge</strong>.</li><li><strong>Tables:</strong> Each table shows its name and number of seats, for example <strong>T4</strong>, 4 seats. A table with open orders shows how many orders and guests it has. Tables can be square, round or wide.</li><li><strong>Zoom:</strong> Use <strong>-</strong>, the percentage and <strong>+</strong> to resize the plan.</li><li><strong>Grid view:</strong> Shows the tables as a simple list of tiles. Use <strong>Map view</strong> to go back.</li><li><strong>Edit plan:</strong> Lets you change the layout. See below.</li><li><strong>+ New order:</strong> Starts an order that is not tied to a table.</li></ul><h2 id="take-a-table-order" tabindex="-1">Take a table order <a class="header-anchor" href="#take-a-table-order" aria-label="Permalink to &quot;Take a table order&quot;">​</a></h2><ol><li>Click the table, for example <strong>T4</strong>. The order screen opens with a <strong>Table T4</strong> chip.</li></ol>',3)),o(a,{src:"/images1/pos/table_order_empty.png",alt:"Table T4 order screen with the Table T4 chip, the Book table button and the food category tiles"}),t[2]||(t[2]=e('<ol start="2"><li>Click a category, such as <strong>Main Course</strong>, then the dishes.</li><li>Select a line and use the number pad <strong>Qty</strong> mode to change the quantity.</li><li>Select a line and click <strong>Note</strong> to add a <strong>Kitchen note</strong>, such as <strong>Wait</strong>.</li></ol>',1)),o(a,{src:"/images1/pos/table_order_lines.png",alt:"Table T4 order with Butter Chicken x2, Margherita Pizza, Mango Lassi x2 with the Wait note and total 1,405"}),t[3]||(t[3]=e('<p><strong>Example:</strong> For table T4 add Butter Chicken x2 (798), Margherita Pizza (349) and Mango Lassi x2 (258). Add the note <strong>Wait</strong> to the Mango Lassi. The total is 1,405.</p><p>Click <strong>Table T4</strong> to go back to the floor plan. The order stays on the table. Click the table again to continue it. Use the <strong>Table</strong> search chip to jump to a table by number.</p><h2 id="actions-on-a-table-order" tabindex="-1">Actions on a table order <a class="header-anchor" href="#actions-on-a-table-order" aria-label="Permalink to &quot;Actions on a table order&quot;">​</a></h2><p>Click <strong>Actions</strong>.</p>',4)),o(a,{src:"/images1/pos/table_actions.png",alt:"Actions window on the table order with Guests, Transfer / Merge and Cancel order"}),t[4]||(t[4]=e('<ul><li><strong>Guests:</strong> Sets the number of guests. The window shows the amount per guest.</li><li><strong>Transfer / Merge:</strong> Moves the order to another table. If that table already has an order, the two orders merge. An order with payments cannot merge.</li><li><strong>Cancel order:</strong> Deletes the order after you confirm.</li><li><strong>Split:</strong> Splits one order into separate orders. It shows when <strong>Allow Bill Splitting</strong> is on.</li><li><strong>Bill:</strong> Prints a receipt before payment. It shows when <strong>Early Receipt Printing</strong> is on.</li><li><strong>Switch to Takeaway</strong> and <strong>Switch to Dine in:</strong> Change the order type when <strong>Eat in / Take out</strong> is on.</li><li><strong>Edit Order Name:</strong> Names an order that has no table, for example &quot;18:45 John 4P&quot;.</li></ul><h3 id="split-an-order" tabindex="-1">Split an order <a class="header-anchor" href="#split-an-order" aria-label="Permalink to &quot;Split an order&quot;">​</a></h3><ol><li>Click <strong>Actions</strong>, then <strong>Split</strong>.</li><li>Tap a line to move one unit to the <strong>New bill</strong>. Tap again to move more.</li><li>Click <strong>Split Order</strong>.</li></ol><p>Each part then has its own payment.</p><h3 id="book-a-table" tabindex="-1">Book a table <a class="header-anchor" href="#book-a-table" aria-label="Permalink to &quot;Book a table&quot;">​</a></h3><p>On a table with no lines, click <strong>Book table</strong>. The table is marked as booked and you return to the floor plan. Click <strong>Release table</strong> to free it.</p><h2 id="edit-the-plan" tabindex="-1">Edit the plan <a class="header-anchor" href="#edit-the-plan" aria-label="Permalink to &quot;Edit the plan&quot;">​</a></h2><ol><li>Click <strong>Edit plan</strong>.</li><li>Drag a table to move it. Drag the corner handle to resize it. Tap a table to edit it.</li><li>Use <strong>Add table</strong>, <strong>Add floor</strong>, <strong>Fewer seats</strong>, <strong>More seats</strong>, <strong>Make round</strong>, <strong>Make square</strong>, <strong>Duplicate</strong> or <strong>Delete table</strong>.</li><li>Set the <strong>Floor name</strong> and the <strong>Floor background</strong>. Add an image if you like.</li></ol>',8)),o(a,{src:"/images1/pos/floor_plan_edit.png",alt:"Edit plan mode with a selected table and the table options Make round, Duplicate and Delete table"}),t[5]||(t[5]=e('<p>You can also manage floors in the back office. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h2 id="pay" tabindex="-1">Pay <a class="header-anchor" href="#pay" aria-label="Permalink to &quot;Pay&quot;">​</a></h2><p>Click <strong>Payment</strong> on the order. The steps are the same as in a shop. See <a href="./pay-and-receipt.html">Pay and receipt</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set <strong>Guests</strong> early. The amount per guest helps when you split the check at the table.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./terminal-overview.html">Terminal tour</a></li><li><a href="./order-notes-and-customers.html">Notes and customers</a></li><li><a href="./../payments-setup/preparation-printers.html">Preparation printers</a></li></ul>',6))])}const T=r(i,[["render",g]]);export{m as __pageData,T as default};
